const baseChar=(o={})=>Object.assign({id:crypto.randomUUID?.()||Date.now()+''+Math.random(),name:'Aventurero',race:'Humano',className:'Guerrero',level:1,xp:0,hp:12,gold:0,dev:0,quest:'tutorialTalk',location:'arca',worldPos:{arca:{x:360,y:350}},startingPoint:'arca',inventory:[],equipment:{weapon:null,offhand:null,helmet:null,armor:'Ropa común',boots:'Botas comunes',gloves:null,ring1:null,ring2:null,amulet:null},tree:{offDamage:0,offLife:0,offIni:0,fury:0,defLife:0,opp:0,guard:0,defIni:0,robust:0},activeAbilities:[]},o);
function fresh(){return {version:2,characters:[],selected:null}}
function migrate(){let s=JSON.parse(localStorage.getItem(KEY)||'null');return s||fresh()}
let state=migrate();save();function save(){localStorage.setItem(KEY,JSON.stringify(state))}function hero(){let c=state.characters[state.selected];if(c&&!Array.isArray(c.activeAbilities))c.activeAbilities=[];return c}
function t(c,k){return c.tree?.[k]||0}function woundRes(c){return (c.equipment.ring1==='Anillo Simple'?1:0)+(c.equipment.ring2==='Anillo Simple'?1:0)}function furyBonus(c,hp=c.hp){let r=t(c,'fury');return r>=2&&hp<=4?2:r>=1&&hp<=3?1:0}function maxHp(c){return 10+(c.equipment.armor==='Ropa común'?1:0)+(c.equipment.boots==='Botas comunes'?1:0)+t(c,'offLife')*2+t(c,'defLife')*2+t(c,'robust')*5+(['Botas de tela','Botas de Cuero'].includes(c.equipment.boots)?2:0)+(c.equipment.helmet==='Casco de Cuero'?2:0)+(c.equipment.armor==='Armadura de cuero de jabalí'?3:0)}function initiative(c){return 4+t(c,'offIni')+t(c,'defIni')}function weaponBonus(name){return name==='Espada de Hierro'?2:(name==='Espada de madera'||name==='Espada básica'||name==='Daga oxidada'?1:0)}function baseDamage(c,hp=c.hp){return 1+t(c,'offDamage')+weaponBonus(c.equipment.weapon)+weaponBonus(c.equipment.offhand)+furyBonus(c,hp)}
function toast(s){document.body.insertAdjacentHTML('beforeend',`<div class="toast">${s}</div>`);setTimeout(()=>$('.toast')?.remove(),1700)}
function modal(html,closable=true){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div class="card">${html}${closable?'<div class="actions"><button class="secondary" onclick="closeModal()">Cerrar</button></div>':''}</div></div>`)}window.closeModal=()=>$('#modal')?.remove();
function home(){app.innerHTML=`<section class="screen center"><div><h1>⚔️ GHEA TÁCTICO</h1><p class="sub">v0.3.0.5 · Interfaz y fichas</p><button id="play">Iniciar</button><p class="small">Prueba sin texturas · Base de combate v0.2.8.32 conservada</p></div></section>`;$('#play').onclick=mainMenu}
function mainMenu(){app.innerHTML=`<section class="screen"><div class="topbar"><b>Ghea Táctico</b><span>v0.3.0.5</span></div><div class="card"><button id="newGame" ${state.characters.length>=3?'disabled':''}>Nueva partida</button><button id="continueGame" ${!state.characters.length?'disabled':''}>Continuar partida</button><button id="options" class="secondary">Opciones</button><button id="exitGame" class="secondary">Salir</button></div><button class="secondary" id="backHome">Volver</button></section>`;$('#newGame').onclick=createChar;$('#continueGame').onclick=characters;$('#options').onclick=()=>toast('Opciones: pendiente.');$('#exitGame').onclick=()=>toast('En navegador/PWA el cierre depende del sistema.');$('#backHome').onclick=home}
function characters(){app.innerHTML=`<section class="screen"><div class="topbar"><b>Continuar partida</b><span>${state.characters.length}/3</span></div><div id="chars"></div><div class="actions"><button id="confirmChar" disabled>Confirmar</button><button class="secondary" id="back">Volver</button></div></section>`;let box=$('#chars'),chosen=null;state.characters.forEach((c,i)=>box.insertAdjacentHTML('beforeend',`<button class="card char-card select-char" data-char="${i}"><div><b>${esc(c.name)}</b> · ${esc(c.race)} ${esc(c.className)} · Nivel ${c.level}<br><span class="small">❤️ ${c.hp}/${maxHp(c)} · ✨ ${c.xp}/${xpNeed(c.level)} · 🪙 ${c.gold}</span></div></button>`));document.querySelectorAll('[data-char]').forEach(b=>b.onclick=()=>{chosen=+b.dataset.char;document.querySelectorAll('[data-char]').forEach(x=>x.classList.toggle('selected-sale',x===b));$('#confirmChar').disabled=false});$('#confirmChar').onclick=()=>{state.selected=chosen;save();world()};$('#back').onclick=mainMenu}
function esc(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
const BAD_WORDS=['puta','puto','mierda','pelotudo','boludo','concha','pija','verga','coger','forro'];
function createChar(){if(state.characters.length>=3)return mainMenu();app.innerHTML=`<section class="screen"><div class="topbar"><b>Nuevo Aventurero</b><span>${state.characters.length+1}/3</span></div><div class="card grid2"><label>Nombre<input id="name" maxlength="16" placeholder="Hasta 16 caracteres"></label><label>Raza<select id="race"><option>Humano</option><option disabled>Enano — próximamente</option><option disabled>Elfo — próximamente</option></select></label><label>Clase<select id="className"><option>Guerrero</option><option disabled>Más clases — próximamente</option></select></label></div><div class="actions"><button id="make">Confirmar</button><button class="secondary" id="cancel">Volver</button></div></section>`;$('#make').onclick=()=>{let name=$('#name').value.trim();if(!name)return toast('Escribí un nombre.');if(name.length>16)return toast('Máximo 16 caracteres.');let low=name.toLowerCase();if(BAD_WORDS.some(w=>low.includes(w)))return toast('Ese nombre no está permitido.');let c=baseChar({name,race:$('#race').value,className:$('#className').value});state.characters.push(c);state.selected=state.characters.length-1;save();world()};$('#cancel').onclick=mainMenu}

