function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}function blocked(map,x,y){let d=mapData[map],r=map==='west'?42:24;if(x<r||y<r||x>d.w-r||y>d.h-r)return true;if(map==='west'){let cell=d.cell,cx=Math.floor(x/cell),cy=Math.floor(y/cell);if(westBlockedCell(cx,cy))return true;}return d.obstacles.some(o=>x+r>o.x&&x-r<o.x+o.w&&y+r>o.y&&y-r<o.y+o.h)}
