function setupWorldZoom(c,pos){let v=$('#worldViewport'),m=$('#worldMap');if(!v||!m)return;let z=worldZoomValue(c);m.style.zoom=z;requestAnimationFrame(()=>{if(c.exploreCamera&&Number.isFinite(c.exploreCamera.left)&&Number.isFinite(c.exploreCamera.top)){v.scrollLeft=c.exploreCamera.left;v.scrollTop=c.exploreCamera.top;clampWorldCamera()}else centerWorldCamera('west',pos,false)});$('#centerCamera')?.addEventListener('click',e=>{e.stopPropagation();centerWorldCamera('west',c.worldPos.west,true)});let pinch=null,oneStart=null,blockClickUntil=0,saveTimer=null;v.addEventListener('scroll',()=>{blockClickUntil=Date.now()+180;clearTimeout(saveTimer);saveTimer=setTimeout(()=>{rememberWorldCamera(c);save()},180)},{passive:true});v.addEventListener('touchstart',e=>{if(e.touches.length===1){oneStart={x:e.touches[0].clientX,y:e.touches[0].clientY}}else if(e.touches.length===2){let a=e.touches[0],b=e.touches[1];pinch={dist:Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY),zoom:worldZoomValue(c)};oneStart=null;blockClickUntil=Date.now()+450}}, {passive:true});v.addEventListener('touchmove',e=>{if(e.touches.length===1&&oneStart){let t=e.touches[0];if(Math.hypot(t.clientX-oneStart.x,t.clientY-oneStart.y)>8)blockClickUntil=Date.now()+250;return}if(!pinch||e.touches.length!==2)return;e.preventDefault();let a=e.touches[0],b=e.touches[1],d=Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY),anchor={x:(a.clientX+b.clientX)/2,y:(a.clientY+b.clientY)/2};applyWorldZoom(pinch.zoom*(d/pinch.dist),anchor);blockClickUntil=Date.now()+450},{passive:false});v.addEventListener('touchend',e=>{if(e.touches.length<2)pinch=null;if(e.touches.length===0)oneStart=null},{passive:true});m.addEventListener('click',e=>{if(Date.now()<blockClickUntil){e.stopImmediatePropagation();e.preventDefault()}},true)}
function centerWorldCamera(map,pos,smooth=true){if(map!=='west')return;let c=hero(),v=$('#worldViewport');if(!v)return;let z=worldZoomValue(c),mw=mapData.west.w*z,mh=mapData.west.h*z,px=pos.x*z,py=pos.y*z,left=Math.max(0,Math.min(Math.max(0,mw-v.clientWidth),px-v.clientWidth/2)),top=Math.max(0,Math.min(Math.max(0,mh-v.clientHeight),py-v.clientHeight/2));v.scrollTo({left,top,behavior:smooth?'smooth':'auto'});setTimeout(()=>{rememberWorldCamera(c);save()},smooth?320:0)}
function pathfind(map,start,goal){const d=mapData[map],step=d.cell||24,cols=d.cols||Math.round(d.w/step),rows=d.rows||Math.round(d.h/step),s={x:clamp(Math.floor(start.x/step),0,cols-1),y:clamp(Math.floor(start.y/step),0,rows-1)},g={x:clamp(Math.floor(goal.x/step),0,cols-1),y:clamp(Math.floor(goal.y/step),0,rows-1)},key=p=>p.x+','+p.y,q=[s],came=new Map([[key(s),null]]);while(q.length){let a=q.shift();if(a.x===g.x&&a.y===g.y)break;for(let [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){let n={x:a.x+dx,y:a.y+dy},k=key(n),px=n.x*step+step/2,py=n.y*step+step/2;if(n.x<0||n.y<0||n.x>=cols||n.y>=rows||came.has(k)||blocked(map,px,py))continue;came.set(k,a);q.push(n)}}if(!came.has(key(g)))return[];let cur=g,out=[];while(cur){out.push({x:cur.x*step+step/2,y:cur.y*step+step/2});cur=came.get(key(cur))}return out.reverse()}
function moveWorld(map,goal,done){let c=hero(),p=c.worldPos[map],path=pathfind(map,p,goal);if(path.length<2){done?.();return}clearInterval(moving);let i=1;moving=setInterval(()=>{if(i>=path.length){clearInterval(moving);moving=null;save();checkTransition(map);done?.();return}let prev=c.worldPos[map],n=path[i++];c.worldPos[map]=n;let el=$('#worldHero');if(el){let dx=n.x-prev.x,dy=n.y-prev.y,dir=Math.abs(dx)>Math.abs(dy)?(dx>0?'derecha':'izquierda'):(dy>0?'abajo':'arriba'),img=el.querySelector('img');if(img)img.src=`assets-miniaturas/guerrero-humano-${dir}.png`;el.style.left=n.x+'px';el.style.top=n.y+'px';if(map==='west'){el.style.zIndex=20+Math.floor(n.y/(mapData.west.cell||64));updateWestTreeOcclusion()}}},90)}
function approachAndInteract(map,target,done,range=62){let c=hero(),p=c.worldPos[map];if(dist(p,target)<=range){done();return}let candidates=[[range,0],[-range,0],[0,range],[0,-range],[range*.7,range*.7],[-range*.7,range*.7],[range*.7,-range*.7],[-range*.7,-range*.7]].map(([dx,dy])=>({x:target.x+dx,y:target.y+dy})).filter(q=>!blocked(map,q.x,q.y));let best=null,bestPath=null;for(let q of candidates){let path=pathfind(map,p,q);if(path.length>1&&(!bestPath||path.length<bestPath.length)){best=q;bestPath=path}}if(!best){toast('No hay un camino libre hasta ese objetivo.');return}moveWorld(map,best,()=>{if(hero()?.location===map&&dist(hero().worldPos[map],target)<=range+28)done()})}
