function setBattleObstacles(sector){obs=new Set();obstacleVisual={};if(!sector?.map||!mapData[sector.map]?.cell){legacyObs.forEach(k=>obs.add(k));Object.assign(obstacleVisual,{'3,3':'rock','3,4':'tree','6,5':'tree','6,6':'rock','7,6':'tree'});return;}let map=sector.map,ox=sector.origin.x,oy=sector.origin.y;for(let y=0;y<10;y++)for(let x=0;x<10;x++){let wx=ox+x,wy=oy+y,k=`${x},${y}`;if(!terrainDef(map,wx,wy).transitable){obs.add(k);obstacleVisual[k]={type:'wall',image:null};}}generatedObstacles(map).forEach(o=>{let visible=[];for(let yy=0;yy<(o.h||1);yy++)for(let xx=0;xx<(o.w||1);xx++){let x=o.x+xx-ox,y=o.y+yy-oy;if(x>=0&&y>=0&&x<10&&y<10){let k=`${x},${y}`;obs.add(k);obstacleVisual[k]={type:'footprint',image:null};visible.push({x,y,k});}}if(!visible.length)return;let anchor=visible.reduce((a,b)=>b.y<a.y||(b.y===a.y&&b.x<a.x)?b:a,visible[0]);let minX=Math.max(o.x,ox),minY=Math.max(o.y,oy),maxX=Math.min(o.x+(o.w||1),ox+10),maxY=Math.min(o.y+(o.h||1),oy+10);obstacleVisual[anchor.k]={type:o.type,image:o.image,w:Math.max(1,maxX-minX),h:Math.max(1,maxY-minY)};})}
