function battleBoardAttrs(){if(B?.worldSector?.map!=='west')return {cls:'',style:''};let o=B.worldSector.origin||{x:0,y:0},px=(o.x/20*100).toFixed(2),py=(o.y/20*100).toFixed(2);return {cls:' sector-west',style:` style="--sector-x:${px}%;--sector-y:${py}%"`}}
function combatPortrait(u){if(u?.type==='hero')return 'assets-fichas/ficha-guerrero.png';if(u?.type==='dummy')return 'assets-fichas/ficha-muneco.png';let src=enemySprite(u);return src||''}
function combatStates(u){let a=[];if(u?.wound>0)a.push(`🩸 Herida ×${u.wound}`);if(u?.poison>0)a.push(`☠️ Veneno ×${u.poison}`);if(u?.burn>0)a.push(`🔥 Quemadura ×${u.burn}`);if(u?.type==='hero'&&furyBonus(hero(),u.hp)>0)a.push(`🔥 Furia +${furyBonus(hero(),u.hp)}`);return a.length?a.join(' · '):'Sin estados'}
function renderDeployment(){let tiles='';for(let y=0;y<10;y++)for(let x=0;x<10;x++){let k=`${x},${y}`,z=occupied(x,y),valid=B.deployTiles.includes(k)&&!obs.has(k)&&!z,chosen=B.deployPos===k,classes=['tile'];if(obs.has(k)&&obstacleClass(k)==='obstacle-wall')classes.push('obstacle','obstacle-wall');if(valid)classes.push('deploy');if(chosen)classes.push('deploy-chosen');tiles+=`<div class="${classes.join(' ')}" data-x="${x}" data-y="${y}">${z?`<div class="unit-piece"><div class="unit-vitals">${z.hp}/${z.max}</div><div class="unit-hp"><i style="width:${Math.max(0,Math.min(100,z.hp/z.max*100))}%"></i></div><span class="unit-icon">${unitVisual(z)}</span></div>`:chosen?`<div class="deploy-hero"><img class="hero-sprite" src="assets-fichas/ficha-guerrero.png" alt=""></div>`:''}</div>`}app.innerHTML=`<section class="screen"><div class="topbar"><b>Despliegue inicial</b><span>Antes de la Ronda 1</span></div><div class="card"><b>Elegí dónde iniciar</b><p class="small">Tocá una de las posiciones resaltadas. Algunas están juntas y otras separadas. La iniciativa y el temporizador comenzarán recién cuando confirmes.</p></div><div class="battle-grid visual-battle${battleBoardAttrs().cls}" id="battleGrid"${battleBoardAttrs().style}>${tiles}${battleObstacleOverlays()}</div><div class="actions deployment-actions"><button id="confirmDeploy" ${B.deployPos?'':'disabled'}>Confirmar posición</button><button class="secondary" id="cancelBattle">Cancelar combate</button></div></section>`;$('#battleGrid').onclick=e=>{let t=e.target.closest('.tile');if(!t)return;let k=`${t.dataset.x},${t.dataset.y}`;if(!B.deployTiles.includes(k)||obs.has(k)||occupied(+t.dataset.x,+t.dataset.y))return;B.deployPos=k;renderDeployment()};$('#confirmDeploy').onclick=()=>{let [x,y]=B.deployPos.split(',').map(Number),h=getU('hero');h.x=x;h.y=y;B.deployment=false;B.deployPos=null;beginTurn()};$('#cancelBattle').onclick=()=>{B=null;world()}}
function cur(){return B.units.find(u=>u.id===B.order[B.turn])}function getU(id){return B.units.find(u=>u.id===id)}function occupied(x,y){return B.units.find(u=>u.x===x&&u.y===y)}function aliveOccupied(x,y){return B.units.find(u=>u.alive&&u.x===x&&u.y===y)}function corpseAt(x,y){return B.units.find(u=>!u.alive&&u.x===x&&u.y===y)}function free(x,y){return x>=0&&y>=0&&x<10&&y<10&&!obs.has(`${x},${y}`)&&!occupied(x,y)}function md(a,b){return Math.abs(a.x-b.x)+Math.abs(a.y-b.y)}function adj8(a,b){return Math.max(Math.abs(a.x-b.x),Math.abs(a.y-b.y))===1}
function beginTurn(){clearInterval(B.timerId);while(!cur()?.alive){B.turn++;if(B.turn>=B.order.length){B.turn=0;B.round++} }let u=cur();u.pa=u.maxPa;u.pm=u.maxPm;u.shield=0;u.uses={};for(let k in u.cd)if(u.cd[k]>0)u.cd[k]--;if(u.type==='hero'&&t(hero(),'guard'))u.shield+=2;if(u.type==='hero'&&hero().equipment.amulet==='Collar de Jabalí')u.shield+=1;if(u.type==='hero'&&hero().equipment.offhand==='Escudo de Madera')u.shield+=1;tickStates(u);if(!u.alive){nextTurn();return}B.timer=30;B.selectedAction=null;B.skillsOpen=false;B.selectedUnitId=u.id;renderBattle();B.timerId=setInterval(()=>{B.timer--;let el=$('#timer');if(el)el.textContent=B.timer+'s';if(B.timer<=0)nextTurn()},1000);if(u.type!=='hero')setTimeout(enemyAI,550)}
function tickStates(u){if(u.wound>0){damage(u,u.wound,false);if(u.type==='hero'&&u.alive){let r=woundRes(hero());if(r)u.wound=Math.max(0,u.wound-r)}}if(u.poison>0&&u.alive)damage(u,u.poison,false);if(u.burn>0&&u.alive)damage(u,u.burn,false)}function nextTurn(){clearInterval(B.timerId);if(checkBattleEnd())return;B.turn++;if(B.turn>=B.order.length){B.turn=0;B.round++}beginTurn()}
function actionInfo(a){let c=hero(),h=getU('hero'),d=baseDamage(c,h?.hp??c.hp);return({move:['Mover','Cada casilla recorrida consume 1 PM. Movimiento ortogonal.','1 PM/casilla','Casilla libre','Hasta PM disponibles','—','—'],normal:['Ataque Normal',`Inflige ${d} de daño con el arma equipada.`,'1 PA','1 enemigo','Adyacente (8 casillas)','2/turno','Sin CD'],power:['Golpe Fuerte',`A.N. +2 (${d+2} daño actual) y Ruptura de Escudo 3.`,'2 PA','1 enemigo','Adyacente','1/turno','CD 1'],block:['Bloqueo','Obtiene +3 Escudo.','1 PA','Propio personaje','Personal','2/turno','Sin CD'],movebody:['Mover cuerpo','Levanta un cadáver adyacente por 1 PA. Mientras lo cargás, moverte cuesta 2 PM por casilla y no podés atacar. Soltarlo es gratis en una casilla libre adyacente.','1 PA al levantar','Cadáver / casilla libre','Adyacente','Sin límite','Sin CD']})[a]}
