const activeDefs={power:{name:'Golpe Fuerte',icon:'💥',cost:'2 PA',range:'Adyacente',uses:'1/turno',cd:'CD 1'},block:{name:'Bloqueo',icon:'🛡️',cost:'1 PA',range:'Personal',uses:'2/turno',cd:'Sin CD'}};
function skillsMenu(){let c=hero();if(!Array.isArray(c.activeAbilities))c.activeAbilities=[];c.activeAbilities=c.activeAbilities.filter(k=>k==='power'||k==='block');let equipped=c.activeAbilities.filter(k=>activeDefs[k]);let available=Object.keys(activeDefs).filter(k=>!equipped.includes(k));let d=baseDamage(c),act=equipped.map(k=>{let a=activeDefs[k],effect=k==='power'?`${d+2} daño + Ruptura de Escudo 3`:'+3 Escudo';return `<button class="sell-row" data-remove-skill="${k}">${a.icon} <b>${a.name}</b><small>${effect} · ${a.cost} · ${a.range} · ${a.uses} · ${a.cd}</small><span>Quitar</span></button>`}).join('')||'<p>Ninguna habilidad activa preparada.</p>';let av=available.map(k=>{let a=activeDefs[k];return `<button class="sell-row" data-add-skill="${k}" ${equipped.length>=6?'disabled':''}>${a.icon} <b>${a.name}</b><span>Equipar</span></button>`}).join('')||'<p class="small">No tenés otras activas aprendidas.</p>';let pass=[];if(t(c,'fury'))pass.push(`🔥 <b>Furia ${t(c,'fury')}/2</b> — ${t(c,'fury')>=2?'Vida ≤4: +2 Daño':'Vida ≤3: +1 Daño'}`);if(t(c,'guard'))pass.push('🛡️ <b>Guardia</b> — +2 Escudo al inicio del turno');if(t(c,'opp'))pass.push(`⚔️ <b>Ataque de Oportunidad</b> — +${t(c,'opp')} daño`);let rings=woundRes(c);if(rings)pass.push(`💍 <b>Resistencia a Herida +${rings}</b> — después del daño de Herida elimina ${rings} carga${rings>1?'s':''}`);app.innerHTML=`<section class="screen"><div class="topbar"><b>Habilidades</b><span>Activas ${equipped.length}/6</span></div><div class="card"><h3>⚔️ Activas equipadas</h3><p class="small">Estas aparecen en combate. Ataque Normal siempre está disponible y no ocupa espacio.</p>${act}</div><div class="card"><h3>📚 Activas disponibles</h3>${av}</div><div class="card"><h3>✨ Pasivas</h3>${pass.length?pass.join('<br><br>'):'<p class="small">Todavía no tenés pasivas.</p>'}</div><button class="secondary" id="backSkills">Volver</button></section>`;document.querySelectorAll('[data-remove-skill]').forEach(b=>b.onclick=()=>{c.activeAbilities=c.activeAbilities.filter(k=>k!==b.dataset.removeSkill);save();skillsMenu()});document.querySelectorAll('[data-add-skill]').forEach(b=>b.onclick=()=>{if(c.activeAbilities.length>=6)return toast('Máximo 6 habilidades activas.');c.activeAbilities.push(b.dataset.addSkill);save();skillsMenu()});$('#backSkills').onclick=world}

let equipMode=null;
function inventory(){let c=hero(),slot=(k,cls)=>`<button class="slot ${cls||''} ${equipMode?.slots.includes(k)?'compatible':''}" data-eq="${k}"><b>${eqLabels[k]}</b><span>${c.equipment[k]||'—'}</span></button>`,bag=Array.from({length:12},(_,i)=>`<button class="bag-slot" ${c.inventory[i]?`data-item="${i}"`:''}>${c.inventory[i]?`🎒 ${c.inventory[i]}`:'—'}</button>`).join('');app.innerHTML=`<section class="screen"><div class="topbar"><b>Inventario</b><span>🪙 ${c.gold}</span></div>${equipMode?`<div class="equip-mode">✨ Tocá uno de los slots iluminados para equipar <b>${esc(equipMode.name)}</b>. <button class="secondary" id="cancelEquip">Cancelar</button></div>`:''}<div class="card equipment-stage"><div class="paperdoll ${c.height==='Baja'?'short':c.height==='Alta'?'tall':''}">🧍</div>${slot('helmet','s-helmet')}${slot('amulet','s-amulet')}${slot('weapon','s-weapon')}${slot('offhand','s-offhand')}${slot('armor','s-armor')}${slot('gloves','s-gloves')}${slot('ring1','s-ring1')}${slot('ring2','s-ring2')}${slot('boots','s-boots')}</div><div class="card"><b>Mochila básica · ${c.inventory.length}/12</b><div class="bag">${bag}</div></div><button class="secondary" id="back">Volver</button></section>`;document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{if(!equipMode)itemInfo(+b.dataset.item)});document.querySelectorAll('[data-eq]').forEach(b=>b.onclick=()=>equipmentSlot(b.dataset.eq));$('#cancelEquip')?.addEventListener('click',()=>{equipMode=null;inventory()});$('#back').onclick=()=>{equipMode=null;world()}}
function itemInfo(i){let c=hero(),name=c.inventory[i],d=itemData[name]||{type:'Objeto',effect:'Sin información adicional.',sell:0};modal(`<h3>${esc(name)}</h3><p><b>Tipo:</b> ${d.type}<br><b>Efecto/Uso:</b> ${d.effect}<br><b>Valor de venta:</b> 🪙 ${d.sell}</p><p class="small">El valor es informativo. La venta se habilitará al interactuar con comerciantes.</p><div class="actions">${d.equip?'<button id="equipItem">Equipar</button>':''}${d.use?'<button id="useItem">Usar</button>':''}<button class="danger" id="discardItem">🗑️ Descartar</button></div>`);$('#equipItem')?.addEventListener('click',()=>{closeModal();equipMode={index:i,name,slots:d.slots||[]};inventory()});$('#useItem')?.addEventListener('click',()=>useConsumable(i,name,d.use));$('#discardItem').onclick=()=>confirmDiscard(i,name)}
function confirmDiscard(i,name){closeModal();modal(`<h3>Descartar objeto</h3><p>¿Descartar <b>${esc(name)}</b>?</p><p class="small">Este objeto se perderá. Descartarlo no otorga oro.</p><div class="actions"><button class="danger" id="doDiscard">Descartar</button><button class="secondary" id="cancelDiscard">Cancelar</button></div>`,false);$('#cancelDiscard').onclick=()=>{closeModal();inventory()};$('#doDiscard').onclick=()=>{let c=hero();if(c.inventory[i]!==name){closeModal();return inventory()}c.inventory.splice(i,1);save();closeModal();inventory();toast(`${name} descartado.`)}}
function equipmentSlot(slot){let c=hero();if(equipMode){if(!equipMode.slots.includes(slot))return toast('Ese objeto no puede ir en este slot.');let i=c.inventory.indexOf(equipMode.name);if(i<0)return;let old=c.equipment[slot];c.equipment[slot]=equipMode.name;c.inventory.splice(i,1);if(old)c.inventory.push(old);c.hp=Math.min(c.hp,maxHp(c));save();let n=equipMode.name;equipMode=null;inventory();if(n==='Espada de madera'&&c.quest==='equipSword'){c.quest='fightDummy';save();setTimeout(()=>toast('Objetivo actualizado: derrotá al Muñeco de Paja.'),250)}toast(`${n} equipado en ${eqLabels[slot]}.`);return}let name=c.equipment[slot];if(!name)return;let d=itemData[name]||{type:'Objeto',effect:'Sin información adicional.',sell:0};modal(`<h3>${esc(name)}</h3><p><b>Equipado en:</b> ${eqLabels[slot]}<br><b>Tipo:</b> ${d.type}<br><b>Efecto:</b> ${d.effect}<br><b>Valor de venta:</b> 🪙 ${d.sell}</p><button id="unequip">Desequipar</button>`);$('#unequip').onclick=()=>unequip(slot)}
function unequip(slot){let c=hero(),name=c.equipment[slot];if(!name)return;if(c.inventory.length>=12)return toast('Necesitás un espacio libre en la mochila.');c.equipment[slot]=null;c.inventory.push(name);c.hp=Math.min(c.hp,maxHp(c));save();closeModal();inventory();toast(`${name} desequipado.`)}
let draft=null,treeBranch=null;const defs={offense:[['offDamage','Daño base','+1 Daño base',3,null],['offLife','Vida','+2 Vida',5,'offFull'],['offIni','Iniciativa','+1 Iniciativa',1,'offFull'],['fury','Furia','Pasiva de Vida baja',2,'offFull']],defense:[['defLife','Vitalidad','+2 Vida',3,null],['opp','Ataque de Oportunidad','+1 daño',1,'defFull'],['guard','Guardia','+2 Escudo al iniciar turno',1,'guardReq'],['defIni','Iniciativa','+1 Iniciativa',1,'defFull'],['robust','Robustez','+5 Vida',2,'vitalFull']]};
function treeMenu(){let c=hero();draft=null;treeBranch=null;app.innerHTML=`<section class="screen"><div class="topbar"><b>Desarrollo</b><span>⭐ ${c.dev} puntos</span></div><p>Elegí un camino para abrir su árbol.</p><div class="branch-choice"><button class="branch" id="off">⚔️<br>OFENSIVA</button><button class="branch" id="def">🛡️<br>DEFENSA</button></div><button class="secondary" id="back">Volver</button></section>`;$('#off').onclick=()=>openTree('offense');$('#def').onclick=()=>openTree('defense');$('#back').onclick=world}
function defensePoints(tree){return (tree.defLife||0)+(tree.opp||0)+(tree.guard||0)+(tree.defIni||0)+(tree.robust||0)}function reqStatus(req){if(!req)return[true,''];if(req==='offFull')return[draft.tree.offDamage>=3,'Requiere Daño base 3/3'];if(req==='defFull'||req==='vitalFull')return[draft.tree.defLife>=3,'Requiere Vitalidad 3/3'];if(req==='guardReq'){let pts=defensePoints(draft.tree),ok=draft.tree.robust>=2&&pts>=6;return[ok,`Requiere Robustez 2/2 y 6 puntos en Defensa (${pts}/6)`]}return[true,'']}
function nodeHtml(d){let [k,name,desc,max,req]=d,[ok,why]=reqStatus(req),locked=!ok,available=!locked&&draft.points>0&&draft.tree[k]<max;return `<button class="tree-node ${locked?'locked':available?'available':''}" data-node="${k}" ${locked||draft.tree[k]>=max?'disabled':''}><b>${name}</b><br><span class="small">${desc}</span><br><strong>${draft.tree[k]}/${max}</strong>${locked?`<span class="requirement">🔒 ${why}</span>`:''}</button>`}
function openTree(branch){let c=hero();treeBranch=branch;if(!draft)draft={tree:structuredClone(c.tree),points:c.dev,history:[]};let arr=defs[branch],rows;if(branch==='offense'){rows=`<div class="tree-row">${nodeHtml(arr[0])}</div><div class="tree-fork"><i></i><i></i><i></i></div><div class="tree-children">${arr.slice(1).map(nodeHtml).join('')}</div>`}else{let vital=arr.find(d=>d[0]==='defLife'),opp=arr.find(d=>d[0]==='opp'),ini=arr.find(d=>d[0]==='defIni'),rob=arr.find(d=>d[0]==='robust'),guard=arr.find(d=>d[0]==='guard');rows=`<div class="tree-level-label">NIVEL 1</div><div class="tree-row">${nodeHtml(vital)}</div><div class="tree-fork defense-fork"><i></i><i></i><i></i></div><div class="tree-children">${nodeHtml(opp)}${nodeHtml(ini)}${nodeHtml(rob)}</div><div class="guard-link"></div><div class="tree-level-label">NIVEL 3 · 6 PUNTOS</div><div class="tree-row">${nodeHtml(guard)}</div>`}app.innerHTML=`<section class="screen"><div class="topbar"><b>${branch==='offense'?'⚔️ Ofensiva':'🛡️ Defensa'}</b><span>⭐ ${draft.points} disponibles</span></div><div class="card tree-view">${rows}</div><div id="nodeExplain" class="card small">Tocá un nodo para asignar un punto. Los requisitos aparecen en los nodos bloqueados.</div><div class="actions"><button id="undo" ${!draft.history.length?'disabled':''}>Deshacer</button><button id="confirm" ${!draft.history.length?'disabled':''}>Confirmar</button><button class="secondary" id="other">Cambiar camino</button><button class="secondary" id="cancelTree">Salir sin confirmar</button></div></section>`;document.querySelectorAll('[data-node]').forEach(b=>{b.onclick=()=>draftSpend(b.dataset.node);b.onpointerdown=()=>showNodeInfo(b.dataset.node)});$('#undo').onclick=draftUndo;$('#confirm').onclick=confirmTree;$('#other').onclick=treeMenu;$('#cancelTree').onclick=world}
function showNodeInfo(k){let d=Object.values(defs).flat().find(x=>x[0]===k),r=draft.tree[k],txt=d[2];if(k==='fury')txt=r>=2?'Vida ≤4: +2 Daño.':r===1?'Vida ≤3: +1 Daño. Siguiente rango: Vida ≤4, +2 Daño.':'Rango 1: Vida ≤3, +1 Daño. Rango 2: Vida ≤4, +2 Daño.';let req=reqStatus(d[4])[1];$('#nodeExplain').innerHTML=`<b>${d[1]} ${r}/${d[3]}</b><br>${txt}${req?`<br>🔒 ${req}`:''}`}
function draftSpend(k){let def=Object.values(defs).flat().find(x=>x[0]===k);if(!def||draft.points<1||draft.tree[k]>=def[3])return;let [ok]=reqStatus(def[4]);if(!ok)return;draft.tree[k]++;draft.points--;draft.history.push(k);openTree(treeBranch)}
function draftUndo(){let k=draft.history.pop();if(!k)return;draft.tree[k]--;draft.points++;openTree(treeBranch)}function confirmTree(){let c=hero();c.tree=structuredClone(draft.tree);c.dev=draft.points;c.hp=Math.min(c.hp,maxHp(c));save();draft=null;toast('Desarrollo confirmado.');treeMenu()}
function testLevelUp(c){c.level++;c.dev+=1;c.hp=maxHp(c);save();toast(`PRUEBA: ${c.name} subió a nivel ${c.level}. +2 Puntos de Desarrollo y Vida completa.`);world()}
function testInstantRest(c){c.hp=maxHp(c);save();toast('PRUEBA: Vida recuperada por completo.');world()}
function testFinishCombat(){if(!B)return;let enemies=B.units.filter(u=>u.type!=='hero'&&u.alive);enemies.forEach(e=>{e.hp=0;e.alive=false});B.log.push('🧪 PRUEBA: todos los enemigos fueron eliminados.');clearInterval(B.timerId);finishBattle(true)}
function rest(c){if(c.hp>=maxHp(c))return toast('Ya tenés la Vida completa.');modal(`<h3>Descanso</h3><p id="restText">Recuperando Vida… ${c.hp}/${maxHp(c)}</p><button id="stop">Terminar descanso</button>`,false);let timer=setInterval(()=>{if(c.hp<maxHp(c)){c.hp++;save();$('#restText').textContent=`Recuperando Vida… ${c.hp}/${maxHp(c)}`}else clearInterval(timer)},5000);$('#stop').onclick=()=>{clearInterval(timer);closeModal();world()}}

