function tutorialObjective(c){return {
 tutorialTalk:'Hablá con el Maestro de la Academia.',equipSword:'Abrí Inventario y equipá la Espada de madera.',fightDummy:'Derrotá al Muñeco de Paja.',returnMaster:'Volvé a hablar con el Maestro.',learnPower:'Abrí Desarrollo y aprendé Golpe Fuerte.',talkPower:'Volvé con el Maestro para iniciar la prueba de Golpe Fuerte.',fightPower:'Usá Golpe Fuerte y derrotá al Muñeco de Paja.',returnPower:'Volvé a hablar con el Maestro.',learnBlock:'Abrí Desarrollo y aprendé Bloqueo.',talkBlock:'Volvé con el Maestro.',fightBlock:'Usá Bloqueo 2 veces y derrotá a los 2 Muñecos.',returnBlock:'Volvé a hablar con el Maestro.',restLesson:'Usá Descansar para completar el ejercicio.',returnRest:'Volvé con el Maestro.',potionLesson:'El Maestro te enseñará a usar una Poción de Vida.',corpseLesson:'Hablá con el Maestro para la última prueba.',returnCorpse:'Volvé con el Maestro.',tutorialComplete:'Tutorial completado. Estás listo para la aventura.'
 }[c.quest]||'Entrenamiento en Arca.'}
