 if(c.quest==='tutorialTalk'){modal(`<h3>Maestro de Arca</h3><p>Bienvenido. Esta es tu última prueba antes de comenzar tu aventura.</p><p>Primero vas a aprender a combatir. Tomá esta <b>Espada de madera</b>.</p><button id="takeSword">Recibir espada</button>`,false);$('#takeSword').onclick=()=>{addItem(c,'Espada de madera');c.quest='equipSword';save();closeModal();world()};return}
 if(c.quest==='equipSword')return toast('Primero equipá la Espada de madera desde Inventario.');
 if(c.quest==='fightDummy')return toast('Derrotá al Muñeco de Paja.');
 if(c.quest==='returnMaster'){c.xp+=1;levelCheck(c);c.quest='learnPower';save();modal(`<h3>Nivel 2</h3><p>Bien. Ahora aprenderás tu primera habilidad.</p><p>Abrí <b>Desarrollo → Ofensiva</b> y aprendé <b>Golpe Fuerte 1/1</b>.</p><button id="goWorld">Continuar</button>`,false);$('#goWorld').onclick=()=>{closeModal();world()};return}
