// v0.3.0.3 — limpieza del rediseño: personajes, habilidades, desarrollo e interfaz compacta.
function sanitizeV0303(c){
 if(!c)return c;
 if(!Array.isArray(c.activeAbilities))c.activeAbilities=[];
 c.activeAbilities=c.activeAbilities.filter(k=>k==='power'||k==='block');
 c.learnedSkills={power:c.activeAbilities.includes('power'),block:c.activeAbilities.includes('block')};
 return c;
}
state.characters.forEach(sanitizeV0303);save();

characters=function(){
 app.innerHTML=`<section class="screen"><div class="topbar"><b>Continuar partida</b><span>${state.characters.length}/3</span></div><div id="chars"></div><div class="actions"><button id="confirmChar" disabled>Confirmar</button><button class="secondary" id="back">Volver</button></div></section>`;
 let box=$('#chars'),chosen=null;
 state.characters.forEach((raw,i)=>{let c=sanitizeV0303(raw);box.insertAdjacentHTML('beforeend',`<div class="card char-save-row"><button class="select-char char-save-main" data-char="${i}"><div><b>${esc(c.name)}</b> · ${esc(c.race)} ${esc(c.className)} · Nivel ${c.level}<br><span class="small">❤️ ${c.hp}/${maxHp(c)} · ✨ ${c.xp}/${xpNeed(c.level)} · 🪙 ${c.gold}</span></div></button><button class="danger delete-char" data-delete-char="${i}">🗑️ Eliminar</button></div>`)});
 document.querySelectorAll('[data-char]').forEach(b=>b.onclick=()=>{chosen=+b.dataset.char;document.querySelectorAll('[data-char]').forEach(x=>x.classList.toggle('selected-sale',x===b));$('#confirmChar').disabled=false});
 document.querySelectorAll('[data-delete-char]').forEach(b=>b.onclick=()=>{let i=+b.dataset.deleteChar,c=state.characters[i];modal(`<h3>Eliminar aventurero</h3><p>¿Seguro que querés eliminar a <b>${esc(c.name)}</b>?</p><p class="small">Esta acción no se puede deshacer.</p><div class="actions"><button class="danger" id="confirmDeleteChar">Eliminar definitivamente</button><button class="secondary" id="cancelDeleteChar">Cancelar</button></div>`,false);$('#cancelDeleteChar').onclick=closeModal;$('#confirmDeleteChar').onclick=()=>{state.characters.splice(i,1);if(state.selected===i)state.selected=null;else if(state.selected>i)state.selected--;save();closeModal();characters();toast('Aventurero eliminado.')}});
 $('#confirmChar').onclick=()=>{state.selected=chosen;save();world()};$('#back').onclick=mainMenu;
};

skillsMenu=function(){
 let c=sanitizeV0303(hero()),learned=[];
 if(c.activeAbilities.includes('power'))learned.push('power');
 if(c.activeAbilities.includes('block'))learned.push('block');
 let cards=learned.map(k=>{let a=activeDefs[k],effect=k==='power'?`${baseDamage(c)+2} daño actual · Ruptura de Escudo 3`:'+3 Escudo';return `<div class="skill-clean-card">${a.icon}<div><b>${a.name}</b><small>${effect}<br>${a.cost} · ${a.range} · ${a.uses} · ${a.cd}</small></div></div>`}).join('');
 app.innerHTML=`<section class="screen compact-menu-screen"><div class="topbar"><b>Habilidades</b><span>Aprendidas ${learned.length}</span></div><div class="card"><h3>✨ Habilidades del aventurero</h3><p class="small">Ataque Normal siempre está disponible y no ocupa un espacio.</p>${cards||'<p>Todavía no aprendiste habilidades.</p>'}</div><button class="secondary" id="backSkills">Volver</button></section>`;
 $('#backSkills').onclick=world;
};

treeMenu=function(){
 let c=sanitizeV0303(hero()),hasPower=c.activeAbilities.includes('power'),hasBlock=c.activeAbilities.includes('block');
 let offenseOpen=c.level>=2, defenseOpen=c.level>=3;
 app.innerHTML=`<section class="screen compact-menu-screen"><div class="topbar"><b>Desarrollo</b><span>⭐ ${c.dev} disponibles</span></div>
 <div class="new-tree-grid">
  <div class="card new-tree-branch"><h3>⚔️ Ofensiva</h3><button class="tree-node ${offenseOpen&&!hasPower?'available':''}" id="newPower" ${!offenseOpen||hasPower?'disabled':''}><b>Golpe Fuerte</b><span>Ataque Normal +2 daño</span><strong>${hasPower?'1/1':'0/1'}</strong></button><div class="tree-link"></div><div class="tree-locked"><b>Próxima rama</b><small>Requiere Golpe Fuerte 1/1 + Nivel 4</small></div></div>
  <div class="card new-tree-branch"><h3>🛡️ Defensa</h3><button class="tree-node ${defenseOpen&&!hasBlock?'available':''}" id="newBlock" ${!defenseOpen||hasBlock?'disabled':''}><b>Bloqueo</b><span>+3 Escudo · 1 PA · 2/turno</span><strong>${hasBlock?'1/1':'0/1'}</strong></button><div class="tree-link"></div><div class="tree-locked"><b>Próxima rama</b><small>Requiere Bloqueo 1/1 + Nivel 4</small></div></div>
 </div><p class="card small">Durante el tutorial se habilitan las dos habilidades iniciales. Las ramas siguientes se completarán con el nuevo árbol del Guerrero.</p><button class="secondary" id="back">Volver</button></section>`;
 $('#newPower').onclick=()=>{if(c.dev<1)return toast('Necesitás 1 punto.');c.dev--;if(!c.activeAbilities.includes('power'))c.activeAbilities.push('power');if(c.quest==='learnPower')c.quest='talkPower';save();toast('Golpe Fuerte aprendido.');treeMenu()};
 $('#newBlock').onclick=()=>{if(c.dev<1)return toast('Necesitás 1 punto.');c.dev--;if(!c.activeAbilities.includes('block'))c.activeAbilities.push('block');if(c.quest==='learnBlock')c.quest='talkBlock';save();toast('Bloqueo aprendido.');treeMenu()};
 $('#back').onclick=world;
};

